if ( in_array( $evidence->document_type, array( 'license','registration','professional_registration' ), true ) ) {
    if ( $accepted ) {
        $matrix['license'] = true;
        $matrix['registration'] = true;
        $matrix['scope_status']['license'] = 'verified';
